    def _run_command(command: list[str]) -> tuple[int, bytes]:
        if color and not sys.platform.startswith("win"):
            master, slave = os.openpty()
            try:
                p = subprocess.Popen(
                    command,
                    stdin=slave,
                    stdout=slave,
                    stderr=slave,
                    close_fds=True,
                )
                os.close(slave)
                out = b""
                while True:
                    try:
                        chunk = os.read(master, 4096)
                        if not chunk:
                            break
                        out += chunk
                    except OSError:
                        break
                return p.wait(), out
            finally:
                try:
                    os.close(master)
                except OSError:
                    pass
