            for j in range(len(exprs)):
                if i == j:
                    continue
                A = exprs[i]
                B = exprs[j]
                # Absorption: A & (A | B) = A
                try:
                    if B == A & (A | B):
                        exprs[j] = A
                        changed = True
                        continue
                except Exception:
                    pass
                # Absorption: A | (A & B) = A
                try:
                    if B == A | (A & B):
                        exprs[j] = A
                        changed = True
                        continue
                except Exception:
                    pass
                # Negative absorption: A & (~A | B) = A & B
                try:
                    if B == A & (~A | B):
                        exprs[j] = A & B
                        changed = True
                        continue
                except Exception:
                    pass
